window.DECK={"level": "all", "cards": [{"id": "n-001", "category": "разговор", "who": "оба", "survey_tag": "разговоры о нас", "text_ru": "По очереди назовите три вещи, которые в партнёре вы замечаете почти каждый день — и обычно не произносите вслух.", "text_en": "Take turns naming three things you notice about your partner almost every day — and almost never say out loud.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-002", "category": "разговор", "who": "один", "survey_tag": "комплименты", "text_ru": "Посмотри на партнёра и вслух опиши, что нравится прямо сейчас: жест, взгляд или деталь в одежде.", "text_en": "Look at your partner and say what you like about them right now — a gesture, a look, or a detail in what they are wearing.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-003", "category": "разговор", "who": "оба", "survey_tag": "разговоры о нас", "text_ru": "Две минуты говорите только о том, в какие моменты рядом с партнёром вам спокойнее всего. Не перебивайте друг друга.", "text_en": "For two minutes, talk only about the moments when you feel most at ease with your partner. Don't interrupt each other.", "seo_ok": false, "timer_sec": 120, "level": "nezhno"}, {"id": "n-004", "category": "разговор", "who": "один", "survey_tag": "благодарности", "text_ru": "Расскажи о недавнем обычном дне, когда тихий поступок партнёра тебя незаметно поддержал. Назови этот поступок.", "text_en": "Tell your partner about a recent ordinary day when something they did quietly held you up. Name that small thing.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-005", "category": "разговор", "who": "оба", "survey_tag": "планы на двоих", "text_ru": "Придумайте вместе одно маленькое дело на ближайшую неделю, которое вы давно откладывали: прогулка, фильм или новый рецепт.", "text_en": "Invent one small thing to do together in the coming week that you have been putting off — a walk, a film, or a new recipe.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-006", "category": "разговор", "who": "один", "survey_tag": "разговоры о нас", "text_ru": "Глядя партнёру в глаза, закончи фразу: «Со мной рядом с тобой легче, когда…»", "text_en": "Looking your partner in the eye, finish this sentence: “Being with you feels easier when…”", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-007", "category": "разговор", "who": "оба", "survey_tag": "благодарности", "text_ru": "По очереди назовите по одной привычке партнёра, за которую вы на самом деле благодарны, хотя она совсем не героическая.", "text_en": "Take turns naming one of your partner's habits you are genuinely grateful for, even though it is not heroic at all.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-008", "category": "разговор", "who": "один", "survey_tag": "разговоры о нас", "text_ru": "Расскажи, какая черта партнёра стала тебе понятнее только спустя время — и что именно в этой черте тебе дорого.", "text_en": "Tell your partner about a quality you only really understood later — and what, exactly, you value in it.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-009", "category": "разговор", "who": "оба", "survey_tag": "планы на двоих", "text_ru": "За три минуты набросайте идеальный тихий вечер дома: что готовите, что слушаете и кто за что отвечает.", "text_en": "In three minutes, sketch an ideal quiet evening at home: what you cook, what you listen to, and who handles what.", "seo_ok": false, "timer_sec": 180, "level": "nezhno"}, {"id": "n-010", "category": "разговор", "who": "один", "survey_tag": "комплименты", "text_ru": "Опиши голос партнёра так, будто рассказываешь человеку, который слышит этот голос впервые.", "text_en": "Describe your partner's voice as if you were telling someone who is hearing it for the first time.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-011", "category": "разговор", "who": "оба", "survey_tag": "разговоры о нас", "text_ru": "Каждый говорит, в чём чувствует себя рядом с партнёром смелее, чем наедине с собой.", "text_en": "Each of you says in what way you feel braver with your partner than you do alone.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-012", "category": "разговор", "who": "один", "survey_tag": "благодарности", "text_ru": "Назови три мелкие вещи, которые партнёр делает по дому или в быту и которые ты уже почти не замечаешь.", "text_en": "Name three small household things your partner does that you have almost stopped noticing.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-013", "category": "разговор", "who": "оба", "survey_tag": "разговоры о нас", "text_ru": "По очереди ответьте одним предложением: «Что в наших отношениях ты хочешь сохранить через пять лет?»", "text_en": "Take turns answering in one sentence: “What in our relationship do you want to still have in five years?”", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-014", "category": "разговор", "who": "один", "survey_tag": "комплименты", "text_ru": "Выбери одну деталь в лице партнёра и честно скажи, почему нравится именно она.", "text_en": "Pick one detail of your partner's face and say, honestly, why that particular one gets to you.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-015", "category": "прикосновение", "who": "один", "survey_tag": "объятия", "text_ru": "Обними партнёра и постойте так две минуты. Не разговаривайте и не гладьте по спине автоматически — просто дышите рядом.", "text_en": "Hold your partner and stay like that for two minutes. Don't talk, and don't automatically rub their back — just breathe together.", "seo_ok": true, "timer_sec": 120, "level": "nezhno"}, {"id": "n-016", "category": "прикосновение", "who": "один", "survey_tag": "массаж рук", "text_ru": "Возьми руки партнёра и три минуты медленно массируй ладони и пальцы. Молчи и смотри на руки, не в телефон.", "text_en": "Take your partner's hands and slowly massage their palms and fingers for three minutes. Stay quiet, and look at their hands, not your phone.", "seo_ok": true, "timer_sec": 180, "level": "nezhno"}, {"id": "n-017", "category": "прикосновение", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Встань за партнёром и три минуты мягко разомни плечи и шею через одежду. Спроси только: сильнее или слабее.", "text_en": "Stand behind your partner and gently work their shoulders and neck, over clothes, for three minutes. The only question allowed is “harder or softer?”", "seo_ok": true, "timer_sec": 180, "level": "nezhno"}, {"id": "n-018", "category": "прикосновение", "who": "оба", "survey_tag": "держать за руки", "text_ru": "Сядьте рядом и минуту просто держитесь за руки. Можно закрыть глаза. Слова подождут.", "text_en": "Sit side by side and just hold hands for a minute. You can close your eyes. Words can wait.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-019", "category": "прикосновение", "who": "один", "survey_tag": "прикосновения", "text_ru": "Проведи кончиками пальцев от запястья партнёра до плеча и обратно. Медленно, по одному разу в каждую сторону, в тишине.", "text_en": "Trace your fingertips from your partner's wrist to their shoulder and back again. Once each way, slowly, in silence.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-020", "category": "прикосновение", "who": "один", "survey_tag": "прикосновения", "text_ru": "Аккуратно расправь волосы партнёра или проведи ладонью по волосам около минуты, как будто просто собираешь их в порядок.", "text_en": "Gently tidy your partner's hair, or run a palm through it for about a minute, as if you were just setting it right.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-021", "category": "прикосновение", "who": "оба", "survey_tag": "тишина рядом", "text_ru": "Сядьте или лягте так, чтобы спина одного касалась груди другого. Две минуты просто будьте в этой позе, без разговоров.", "text_en": "Sit or lie so that one of you has their back against the other's chest. Stay like that for two minutes, without talking.", "seo_ok": false, "timer_sec": 120, "level": "nezhno"}, {"id": "n-022", "category": "прикосновение", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Попроси партнёра сесть удобно и две минуты рисуй ладонями медленные круги по спине через одежду.", "text_en": "Ask your partner to sit comfortably, then draw slow circles on their back with your palms, over clothes, for two minutes.", "seo_ok": false, "timer_sec": 120, "level": "nezhno"}, {"id": "n-023", "category": "прикосновение", "who": "один", "survey_tag": "забота", "text_ru": "Устрой партнёру удобное место: подушка, плед, чуть приглуши свет. Потом сядь рядом, не ожидая благодарности.", "text_en": "Make your partner comfortable: a pillow, a blanket, the light turned down a little. Then sit nearby, without waiting to be thanked.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-024", "category": "прикосновение", "who": "один", "survey_tag": "прикосновения", "text_ru": "Возьми лицо партнёра в ладони на несколько секунд, посмотри в глаза и улыбнись. Можно ничего не говорить.", "text_en": "Cup your partner's face in your hands for a few seconds, look them in the eye, and smile. You don't have to say anything.", "seo_ok": false, "timer_sec": 30, "level": "nezhno"}, {"id": "n-025", "category": "прикосновение", "who": "оба", "survey_tag": "массаж рук", "text_ru": "Сядьте напротив друг друга и одновременно массируйте правую руку партнёра две-три минуты. Потом поменяйтесь руками.", "text_en": "Sit facing each other and massage each other's right hand for two or three minutes. Then switch hands.", "seo_ok": false, "timer_sec": 180, "level": "nezhno"}, {"id": "n-026", "category": "прикосновение", "who": "один", "survey_tag": "объятия", "text_ru": "Подойди сзади и обними партнёра за плечи на тридцать секунд. Не пугай и не подскакивай — просто появись рядом.", "text_en": "Come up from behind and put your arms around your partner's shoulders for thirty seconds. Don't startle them — just arrive.", "seo_ok": false, "timer_sec": 30, "level": "nezhno"}, {"id": "n-027", "category": "прикосновение", "who": "один", "survey_tag": "держать за руки", "text_ru": "Переплети пальцы с партнёром и минуту слегка сжимай и отпускай ладонь в ритме своего дыхания.", "text_en": "Interlace your fingers with your partner's and, for a minute, gently squeeze and release in time with your breathing.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-028", "category": "прикосновение", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Попроси партнёра опустить плечи и две минуты большими пальцами мягко разотри основание шеи. Если где-то неприятно — сразу остановись.", "text_en": "Ask your partner to drop their shoulders, then use your thumbs to gently work the base of their neck for two minutes. If anything hurts, stop at once.", "seo_ok": false, "timer_sec": 120, "level": "nezhno"}, {"id": "n-029", "category": "игра", "who": "оба", "survey_tag": "игры взглядами", "text_ru": "Смотрите друг другу в глаза целую минуту, не разговаривая. Кто первый засмеётся, говорит, что было видно в лице другого.", "text_en": "Look into each other's eyes for a full minute without talking. Whoever laughs first says what they noticed in the other's face.", "seo_ok": true, "timer_sec": 60, "level": "nezhno"}, {"id": "n-030", "category": "игра", "who": "оба", "survey_tag": "угадайки о нас", "text_ru": "Каждый пишет ответ на вопрос: «Что я хочу на ужин прямо сейчас?» Потом угадайте ответ партнёра.", "text_en": "Each of you writes down the answer to: “What do I want for dinner right now?” Then try to guess your partner's answer.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-031", "category": "игра", "who": "один", "survey_tag": "весёлые задания", "text_ru": "Шестьдесят секунд изображай партнёра: любимую позу на диване, жест, привычную фразу. Без подкола, только с теплом.", "text_en": "For sixty seconds, impersonate your partner: their favourite sofa pose, a gesture, a phrase they always use. Keep it warm, not sharp.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-032", "category": "игра", "who": "оба", "survey_tag": "угадайки о нас", "text_ru": "Назовите по очереди пять вещей, которые точно лежат в сумке или карманах партнёра. За каждое попадание — короткое объятие.", "text_en": "Take turns naming five things that are definitely in your partner's bag or pockets. Each correct guess earns a short hug.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-033", "category": "игра", "who": "оба", "survey_tag": "медленный танец", "text_ru": "Включите любую спокойную песню и две минуты медленно потанцуйте в комнате. Можно совсем без шагов, просто качаться в обнимку.", "text_en": "Put on any quiet song and slow-dance around the room for two minutes. You can skip the steps and just sway, holding each other.", "seo_ok": true, "timer_sec": 120, "level": "nezhno"}, {"id": "n-034", "category": "игра", "who": "оба", "survey_tag": "угадайки о нас", "text_ru": "Загадайте каждый по одному событию из вашей общей недели. Партнёр задаёт три уточняющих вопроса и пробует угадать, что это было.", "text_en": "Each of you thinks of one moment from your shared week. Your partner may ask three questions, then try to guess which moment it was.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-035", "category": "игра", "who": "один", "survey_tag": "забота", "text_ru": "За минуту собери партнёру маленький поднос из того, что под рукой: вода или чай, что-то съестное, плед или зарядка.", "text_en": "In one minute, put together a small tray for your partner from whatever is within reach: water or tea, a snack, a blanket or a charger.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-036", "category": "игра", "who": "оба", "survey_tag": "игры взглядами", "text_ru": "Сядьте близко. Один показывает взглядом и мимикой настроение, второй угадывает одним словом. По три попытки на каждого.", "text_en": "Sit close. One of you shows a mood with only their eyes and face; the other guesses it in a single word. Three turns each.", "seo_ok": false, "timer_sec": 90, "level": "nezhno"}, {"id": "n-037", "category": "игра", "who": "оба", "survey_tag": "угадайки о нас", "text_ru": "Каждый называет песню, которая напоминает о партнёре, и объясняет почему. Если песня под рукой — включите короткий фрагмент.", "text_en": "Each of you names a song that reminds you of your partner, and says why. If you have it handy, play a short clip.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-038", "category": "игра", "who": "один", "survey_tag": "весёлые задания", "text_ru": "Минуту говори с партнёром, не используя слова «я» и «ты». Если слово сорвалось — улыбнись и начни фразу заново.", "text_en": "Talk to your partner for a minute without using the words “I” or “you”. If you slip, smile and start the sentence over.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-039", "category": "игра", "who": "оба", "survey_tag": "фото вместе", "text_ru": "Сделайте одно совместное фото так, будто это кадр из спокойного фильма. Позу придумайте вместе, без гримас в камеру.", "text_en": "Take one photo together as if it were a still from a quiet film. Invent the pose together, and skip the camera faces.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-040", "category": "игра", "who": "оба", "survey_tag": "весёлые задания", "text_ru": "Две минуты вспоминайте, как вы познакомились, и каждый добавляет по одной явно выдуманной детали. Потом решите, какая ложь звучала правдоподобнее.", "text_en": "For two minutes, retell how you met, each adding one clearly invented detail. Then decide together which lie sounded the most believable.", "seo_ok": false, "timer_sec": 120, "level": "nezhno"}, {"id": "n-041", "category": "флирт", "who": "один", "survey_tag": "флирт без продолжения", "text_ru": "Подойди ближе, чем обычно, и шёпотом скажи партнёру один комплимент, который не про внешность.", "text_en": "Come closer than usual and whisper one compliment that has nothing to do with how your partner looks.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-042", "category": "флирт", "who": "один", "survey_tag": "шёпот", "text_ru": "Наклонись к партнёру и шёпотом расскажи, что в этой улыбке тебя каждый раз подкупает.", "text_en": "Lean in and whisper what it is about your partner's smile that gets you every time.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-043", "category": "флирт", "who": "оба", "survey_tag": "игры взглядами", "text_ru": "Тридцать секунд смотрите друг на друга так, будто увидели впервые и вам нельзя заговорить. Потом расскажите, что заметили.", "text_en": "Spend thirty seconds looking at each other as if you had just met and were not allowed to speak. Then say what you noticed.", "seo_ok": false, "timer_sec": 30, "level": "nezhno"}, {"id": "n-044", "category": "флирт", "who": "один", "survey_tag": "флирт без продолжения", "text_ru": "Напиши на ладони партнёра одно короткое слово, которое ты сейчас к этому человеку чувствуешь. Пусть прочитает молча.", "text_en": "Write one short word on your partner's palm for what you feel toward them right now. Let them read it in silence.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-045", "category": "флирт", "who": "один", "survey_tag": "записки и послания", "text_ru": "Отойди на минуту и оставь партнёру короткую записку там, где её точно найдут сегодня вечером.", "text_en": "Step away for a minute and leave your partner a short note where they will definitely find it later tonight.", "seo_ok": true, "timer_sec": 60, "level": "nezhno"}, {"id": "n-046", "category": "флирт", "who": "один", "survey_tag": "шёпот", "text_ru": "Сядь так, чтобы говорить почти в ухо, и за тридцать секунд назови три вещи в партнёре, которые для тебя самые «домашние» и родные.", "text_en": "Sit close enough to speak almost into your partner's ear, and in thirty seconds name three things about them that feel like home to you.", "seo_ok": false, "timer_sec": 30, "level": "nezhno"}, {"id": "n-047", "category": "флирт", "who": "оба", "survey_tag": "флирт без продолжения", "text_ru": "По очереди подмигните, улыбнитесь или сделайте едва заметный жест, как будто вы в кафе и не хотите, чтобы вас подслушали.", "text_en": "Take turns winking, smiling, or making a tiny gesture, as if you were in a café and did not want to be overheard.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-048", "category": "флирт", "who": "один", "survey_tag": "комплименты", "text_ru": "Сравни партнёра не с идеалом, а с чем-то простым и точным: с утренним светом, любимой кружкой, знакомой улицей. Объясни сравнение.", "text_en": "Compare your partner not to an ideal, but to something plain and exact: morning light, a favourite mug, a familiar street. Then explain the comparison.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-049", "category": "флирт", "who": "один", "survey_tag": "записки и послания", "text_ru": "Отправь партнёру одно сообщение с соседнего дивана или из другой комнаты: одну фразу, без смайликов, будто это начало письма.", "text_en": "Send your partner one message from the other end of the sofa, or from the next room: a single sentence, no emojis, as if it were the opening of a letter.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-050", "category": "флирт", "who": "оба", "survey_tag": "флирт без продолжения", "text_ru": "Минуту говорите друг с другом только вопросами, и каждый вопрос должен быть чуть теплее предыдущего.", "text_en": "Speak only in questions for a minute, and each question has to be a little warmer than the last.", "seo_ok": false, "timer_sec": 60, "level": "nezhno"}, {"id": "n-051", "category": "воспоминание", "who": "оба", "survey_tag": "воспоминания", "text_ru": "Вспомните вместе вашу первую встречу. Каждый добавляет одну деталь, которую, как кажется, второй мог забыть.", "text_en": "Together, go back to the first time you met. Each of you adds one detail you suspect the other might have forgotten.", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-052", "category": "воспоминание", "who": "один", "survey_tag": "воспоминания", "text_ru": "Расскажи о моменте, когда впервые стало ясно: «С этим человеком мне безопасно». Что тогда происходило вокруг?", "text_en": "Tell your partner about the moment it first became clear: “I feel safe with this person.” What was going on around you?", "seo_ok": true, "timer_sec": null, "level": "nezhno"}, {"id": "n-053", "category": "воспоминание", "who": "оба", "survey_tag": "воспоминания", "text_ru": "Назовите по очереди самый смешной случай, который случался с вами в поездке, в гостях или просто дома на кухне.", "text_en": "Take turns naming the funniest thing that has happened to you on a trip, at someone's house, or just in your own kitchen.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-054", "category": "воспоминание", "who": "один", "survey_tag": "воспоминания", "text_ru": "Опиши ваш обычный день так, как ты его запомнишь через десять лет: не праздник, а самую обычную субботу.", "text_en": "Describe an ordinary day of yours the way you think you will remember it in ten years — not a celebration, just a regular Saturday.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-055", "category": "воспоминание", "who": "оба", "survey_tag": "воспоминания", "text_ru": "Вспомните первый совместный праздник или первый вечер, когда вы остались совсем одни. Что тогда готовили или слушали?", "text_en": "Remember your first celebration together, or the first evening you had completely to yourselves. What did you cook, or put on to listen to?", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-056", "category": "воспоминание", "who": "один", "survey_tag": "воспоминания", "text_ru": "Расскажи о комплименте партнёра, который ты всё ещё помнишь, хотя он был сказан давно и, может быть, вскользь.", "text_en": "Tell your partner about a compliment of theirs you still remember, even if it was said long ago, and maybe only in passing.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-057", "category": "воспоминание", "who": "оба", "survey_tag": "воспоминания", "text_ru": "Выберите фото из вашей галереи — любое старое, не обязательно удачное — и расскажите, что было за секунду до снимка и сразу после.", "text_en": "Pick a photo from your camera roll — any old one, it doesn't have to be flattering — and tell the story of the second before it, and the second after.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-058", "category": "воспоминание", "who": "один", "survey_tag": "воспоминания", "text_ru": "Расскажи, как выглядел обычный вечер у вас дома в первый месяц вместе — и чем он отличается от сегодняшнего.", "text_en": "Describe an ordinary evening at home in your first month together — and how it differs from an evening now.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-059", "category": "воспоминание", "who": "оба", "survey_tag": "планы на двоих", "text_ru": "Вспомните место, куда вы оба хотите вернуться. Каждый говорит, что будет там делать в первый час.", "text_en": "Think of a place you both want to go back to. Each of you says what you would do there in the first hour.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "n-060", "category": "воспоминание", "who": "один", "survey_tag": "воспоминания", "text_ru": "Расскажи историю вашей пары так, будто это короткий фильм: где начинается, какой там свет, и на каком кадре стоит поставить паузу.", "text_en": "Tell the story of the two of you as if it were a short film: where it starts, what the light is like, and on which frame you would hit pause.", "seo_ok": false, "timer_sec": null, "level": "nezhno"}, {"id": "t-001", "category": "поцелуи", "who": "оба", "survey_tag": "поцелуи", "text_ru": "Целуйтесь минуту так медленно, как только можете. Если мысли уходят в сторону — просто начните сначала.", "text_en": "Kiss for a full minute, as slowly as you possibly can. If your mind wanders, just start over.", "seo_ok": false, "timer_sec": 60, "level": "teplo"}, {"id": "t-002", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи", "text_ru": "Поцелуй партнёра в шею, у самого уха — один раз, но так, чтобы он это запомнил.", "text_en": "Kiss your partner on the neck, right by the ear — just once, but make it one they'll remember.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-003", "category": "поцелуи", "who": "оба", "survey_tag": "поцелуи", "text_ru": "Две минуты целуйтесь только в губы, без рук. Руки — за спиной, как в школьном дворе.", "text_en": "Two minutes of kissing, lips only, no hands. Keep them behind your backs, like teenagers.", "seo_ok": false, "timer_sec": 120, "level": "teplo"}, {"id": "t-004", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи", "text_ru": "Расцелуй партнёру ладонь, запястье и внутреннюю сторону локтя. Следи за реакцией: что нравится больше всего?", "text_en": "Kiss your partner's palm, wrist and the inside of the elbow. Watch the reaction: which spot wins?", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-005", "category": "поцелуи", "who": "оба", "survey_tag": "поцелуи", "text_ru": "Поцелуйтесь пять раз по-разному: быстро, нежно, игриво, долго и «как в кино». Угадайте, какой поцелуй какой.", "text_en": "Kiss five different ways: quick, tender, playful, long, and \"movie-style\". Then guess which was which.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-006", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи", "text_ru": "Закрой партнёру глаза ладонью и поцелуй там, где он не ждёт — в плечо, висок или ключицу.", "text_en": "Cover your partner's eyes and kiss somewhere unexpected — shoulder, temple or collarbone.", "seo_ok": false, "timer_sec": 30, "level": "teplo"}, {"id": "t-007", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи", "text_ru": "Поцелуй партнёра так, как целовал бы в самый первый раз. Потом расскажи, что тогда чувствовал.", "text_en": "Kiss your partner the way you would have the very first time. Then tell them what you felt back then.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-008", "category": "шёпот", "who": "один", "survey_tag": "шёпот", "text_ru": "Прошепчи партнёру на ухо, что тебе в нём нравится больше всего. Только шёпотом и только честно.", "text_en": "Whisper in your partner's ear what you like most about them. Whisper only, and only the truth.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-009", "category": "шёпот", "who": "один", "survey_tag": "шёпот", "text_ru": "Прошепчи, что бы ты сделал с партнёром сегодня вечером, будь у вас больше времени. Подробности — на твоё усмотрение.", "text_en": "Whisper what you would do with your partner tonight if you had all the time in the world. Details are up to you.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-010", "category": "шёпот", "who": "оба", "survey_tag": "шёпот", "text_ru": "Весь следующий круг карточек общайтесь только шёпотом, даже если дома никого нет.", "text_en": "For the next round of cards, speak only in whispers — even if nobody else is home.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-011", "category": "шёпот", "who": "один", "survey_tag": "шёпот", "text_ru": "Прошепчи партнёру три слова, которые заставят его улыбнуться. Он угадывает, какое было самым искренним.", "text_en": "Whisper three words that will make your partner smile. They guess which one was the most sincere.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-012", "category": "массаж", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Сделай партнёру пятиминутный массаж плеч и шеи. Спрашивай, как лучше: сильнее или мягче.", "text_en": "Give your partner a five-minute shoulder and neck massage. Ask what feels best: firmer or softer.", "seo_ok": false, "timer_sec": 300, "level": "teplo"}, {"id": "t-013", "category": "массаж", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Партнёр ложится на живот. Ты рисуешь пальцами на его спине слова — он угадывает, что ты написал.", "text_en": "Your partner lies on their stomach. You trace words on their back with a fingertip — they guess what you wrote.", "seo_ok": false, "timer_sec": 180, "level": "teplo"}, {"id": "t-014", "category": "массаж", "who": "один", "survey_tag": "массаж ног", "text_ru": "Сделай партнёру массаж стоп: тёплыми руками, не торопясь. Если щекотно — скажи, и сменим приём.", "text_en": "Give your partner a foot massage with warm hands, no rush. If it tickles, say so and switch technique.", "seo_ok": false, "timer_sec": 300, "level": "teplo"}, {"id": "t-015", "category": "массаж", "who": "оба", "survey_tag": "массаж плеч и спины", "text_ru": "Сядьте друг за другом цепочкой и одновременно сделайте массаж плеч. Через три минуты поменяйтесь местами.", "text_en": "Sit one behind the other and give each other shoulder massages at the same time. Swap after three minutes.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-016", "category": "массаж", "who": "один", "survey_tag": "массаж ног", "text_ru": "Помассируй партнёру икры и ступни, пока он рассказывает тебе о лучшем дне за последний месяц.", "text_en": "Massage your partner's calves and feet while they tell you about the best day of the past month.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-017", "category": "массаж", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Проведи кончиками пальцев по спине партнёра так легко, чтобы по коже побежали мурашки. Две минуты.", "text_en": "Run your fingertips over your partner's back so lightly that it gives them goosebumps. Two minutes.", "seo_ok": false, "timer_sec": 120, "level": "teplo"}, {"id": "t-018", "category": "флирт", "who": "оба", "survey_tag": "флирт", "text_ru": "Сыграйте, что вы случайно встретились в кафе и впервые заговорили. Представьтесь по-новому и пофлиртуйте минут пять.", "text_en": "Play out meeting by chance in a café and talking for the first time. Introduce yourselves anew and flirt for five minutes.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-019", "category": "флирт", "who": "один", "survey_tag": "флирт", "text_ru": "Сделай партнёру комплимент, который ты ещё никогда не говорил, — с самым серьёзным лицом.", "text_en": "Give your partner a compliment you've never said before — with the most serious face you can manage.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-020", "category": "флирт", "who": "оба", "survey_tag": "флирт", "text_ru": "Смотрите друг другу в глаза и не улыбайтесь. Кто первый засмеётся или отведёт взгляд — выполняет желание другого (в рамках приличий и стоп-слова).", "text_en": "Look into each other's eyes and don't smile. Whoever laughs or looks away first grants the other a small wish (within reason, and the stop word still applies).", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-021", "category": "флирт", "who": "один", "survey_tag": "флирт", "text_ru": "Отправь партнёру голосовое или записку, которую он прочтёт позже: что-то игривое про сегодняшний вечер.", "text_en": "Leave your partner a voice note or a written one to find later: something playful about tonight.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-022", "category": "флирт", "who": "один", "survey_tag": "флирт", "text_ru": "Скажи партнёру: «Я только что поймал себя на мысли…» — и закончи фразу так, как захочется.", "text_en": "Tell your partner: \"I just caught myself thinking…\" — and finish the sentence however you like.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-023", "category": "игра", "who": "оба", "survey_tag": "дразнилки", "text_ru": "Дразните друг друга по очереди: можно только смотреть и говорить, а трогать — нельзя. Две минуты, потом поменяйтесь.", "text_en": "Tease each other in turns: only looking and talking, no touching. Two minutes each, then swap.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-024", "category": "игра", "who": "один", "survey_tag": "дразнилки", "text_ru": "Подойди к партнёру почти вплотную и замри на минуту — не касаясь. Что чувствуете оба?", "text_en": "Step almost close enough to touch your partner and hold still for a minute — without touching. What do you both feel?", "seo_ok": false, "timer_sec": 60, "level": "teplo"}, {"id": "t-025", "category": "игра", "who": "оба", "survey_tag": "лёгкое раздевание", "text_ru": "Сыграйте в «камень-ножницы-бумага»: проигравший снимает один носок, украшение или другую мелочь. Три раунда, дальше — по желанию.", "text_en": "Play rock-paper-scissors: the loser takes off one sock, piece of jewellery or something small. Three rounds, anything beyond that is optional.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-026", "category": "игра", "who": "один", "survey_tag": "лёгкое раздевание", "text_ru": "Выбери одну вещь одежды партнёра и медленно сними её сам — если он согласен. Если нет, выбери другую или пропусти.", "text_en": "Pick one item of your partner's clothing and slowly take it off — if they're happy with it. If not, choose another or skip.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-027", "category": "игра", "who": "один", "survey_tag": "лёгкое раздевание", "text_ru": "Сними одну вещь из одежды, глядя партнёру в глаза. Не торопись и не снимай больше, чем решил.", "text_en": "Take off one item of clothing while looking your partner in the eye. Don't rush, and don't remove more than you decided.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-028", "category": "игра", "who": "оба", "survey_tag": "лёгкое раздевание", "text_ru": "Поменяйтесь одной вещью — рубашкой, свитером, футболкой. Надень её и пройдись, как по подиуму.", "text_en": "Swap one item of clothing — a shirt, a sweater, a tee. Put it on and strut like it's a catwalk.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-029", "category": "игра", "who": "оба", "survey_tag": "дразнилки", "text_ru": "Придумайте друг другу по одному «долгу» на сегодня: что нужно получить от партнёра до конца вечера. Выполнять можно в любое время.", "text_en": "Think up one \"debt\" for each other for tonight — something to collect from your partner before the evening ends. They can pay up any time.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-030", "category": "ощущения", "who": "один", "survey_tag": "флирт", "text_ru": "Проведи по руке партнёра чем-то неожиданным: шарфом, тканью, кончиками волос. Пусть угадает, что это.", "text_en": "Draw something unexpected along your partner's arm: a scarf, a bit of fabric, the ends of your hair. Let them guess what it is.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-031", "category": "ощущения", "who": "один", "survey_tag": "массаж плеч и спины", "text_ru": "Подуй партнёру на шею и плечи — тихо и тепло. Потом поцелуй то место, где было приятнее всего.", "text_en": "Blow softly on your partner's neck and shoulders — gentle and warm. Then kiss the spot where it felt best.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-032", "category": "танец", "who": "оба", "survey_tag": "танец", "text_ru": "Включите медленную песню и танцуйте, прижавшись друг к другу. Закройте глаза хотя бы на половину песни.", "text_en": "Put on a slow song and dance pressed close together. Close your eyes for at least half of it.", "seo_ok": false, "timer_sec": 240, "level": "teplo"}, {"id": "t-033", "category": "танец", "who": "оба", "survey_tag": "танец", "text_ru": "Танцуйте под любимую песню партнёра. Ведёт тот, чья песня, второй просто доверяется.", "text_en": "Dance to your partner's favourite song. The owner of the song leads, the other simply trusts.", "seo_ok": false, "timer_sec": 180, "level": "teplo"}, {"id": "t-034", "category": "танец", "who": "один", "survey_tag": "танец", "text_ru": "Пригласи партнёра на танец так, как будто это бал в старинном зале. Поклон обязателен.", "text_en": "Invite your partner to dance as if it were a ball in an old grand hall. A bow is mandatory.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-035", "category": "разговор", "who": "оба", "survey_tag": "шёпот", "text_ru": "По очереди расскажите, какое прикосновение друг от друга вы любите больше всего. Только шёпотом, нос к носу.", "text_en": "Take turns saying which touch from each other you love the most. Whisper only, nose to nose.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-036", "category": "разговор", "who": "оба", "survey_tag": "флирт", "text_ru": "Вспомните свой самый волнующий момент вместе. Расскажите его вслух так, как будто это сцена из фильма.", "text_en": "Recall your most thrilling moment together. Tell it out loud as if it were a scene from a film.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-037", "category": "разговор", "who": "один", "survey_tag": "дразнилки", "text_ru": "Расскажи партнёру, в какой момент дня ты чаще всего о нём думаешь — и что именно в этот момент приходит в голову.", "text_en": "Tell your partner when in the day you think about them most — and what exactly crosses your mind.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-038", "category": "ощущения", "who": "оба", "survey_tag": "поцелуи", "text_ru": "Сядьте лицом к лицу так близко, что чувствуете дыхание друг друга. Минуту молчите и ничего не делайте.", "text_en": "Sit face to face, close enough to feel each other's breath. Stay silent and do nothing for one minute.", "seo_ok": false, "timer_sec": 60, "level": "teplo"}, {"id": "t-039", "category": "поцелуи", "who": "оба", "survey_tag": "поцелуи", "text_ru": "Целуйтесь, пока играет одна песня. Если песня закончилась, а вы нет — продолжайте до конца следующей.", "text_en": "Kiss for the length of one song. If the song ends and you don't, carry on until the next one is over.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "t-040", "category": "флирт", "who": "оба", "survey_tag": "лёгкое раздевание", "text_ru": "Устройте «модный показ»: каждый примеряет два образа из своего шкафа для партнёра. Жюри — партнёр, оценки только комплиментами.", "text_en": "Hold a \"fashion show\": each of you tries two outfits from your wardrobe for the other. The partner is the jury, and scores are given in compliments only.", "seo_ok": false, "timer_sec": null, "level": "teplo"}, {"id": "g-001", "category": "ощущения", "who": "один", "survey_tag": "повязка на глаза", "text_ru": "Завяжи партнёру глаза и три минуты целуй его в разные места, не говоря ни слова. Пусть пытается угадать, где будет следующий поцелуй.", "text_en": "Blindfold your partner and kiss different spots for three minutes without a word. Let them try to guess where the next one lands.", "seo_ok": false, "timer_sec": 180, "level": "goryacho"}, {"id": "g-002", "category": "ощущения", "who": "один", "survey_tag": "повязка на глаза", "text_ru": "Партнёр с завязанными глазами. Ты шёпотом даёшь ему простые указания: «поверни голову», «протяни руку». Стоп-слово в силе.", "text_en": "Your partner is blindfolded. You whisper simple instructions: \"turn your head\", \"reach out\". The stop word stands.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-003", "category": "ощущения", "who": "один", "survey_tag": "повязка на глаза", "text_ru": "Надень повязку сам и дай партнёру решать, к чему ты прикоснёшься и что услышишь. Скажи «стоп», как только захочешь.", "text_en": "Put the blindfold on yourself and let your partner decide what you touch and what you hear. Say \"stop\" whenever you want.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-004", "category": "ощущения", "who": "оба", "survey_tag": "повязка на глаза", "text_ru": "Завяжите глаза обоим и найдите друг друга на ощупь в комнате. Когда нашлись — обнимитесь покрепче.", "text_en": "Blindfold both of you and find each other by touch around the room. Once you do — hold each other tight.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-005", "category": "ощущения", "who": "один", "survey_tag": "повязка на глаза", "text_ru": "С завязанными глазами партнёр угадывает по поцелую, где ты его целуешь: плечо, шея, запястье, живот. Три попытки.", "text_en": "With the blindfold on, your partner guesses where you're kissing them: shoulder, neck, wrist, stomach. Three tries.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-006", "category": "ощущения", "who": "один", "survey_tag": "ощущения", "text_ru": "Проведи по коже партнёра кубиком льда — медленно, по линии плеча и спины. Потом согрей это место дыханием.", "text_en": "Slide an ice cube slowly along your partner's shoulder and back. Then warm that spot with your breath.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-007", "category": "ощущения", "who": "один", "survey_tag": "ощущения", "text_ru": "Партнёр с закрытыми глазами. Проведи по нему пёрышком, шёлковым шарфом и своими губами. Пусть угадает порядок.", "text_en": "Your partner closes their eyes. Trail a feather, a silk scarf and your lips over them. Let them guess the order.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-008", "category": "ощущения", "who": "один", "survey_tag": "ощущения", "text_ru": "Положи партнёру на кожу что-то тёплое, а потом что-то прохладное. Спроси, что больше нравится.", "text_en": "Place something warm and then something cool on your partner's skin. Ask which they like more.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-009", "category": "ощущения", "who": "оба", "survey_tag": "ощущения", "text_ru": "Устройте «дегустацию»: завяжите глаза и по очереди угощайте друг друга виноградом, шоколадом или мороженым. Сладкое можно доедать губами.", "text_en": "Hold a \"tasting\": blindfolded, take turns feeding each other grapes, chocolate or ice cream. Finish the sweet part with your lips.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-010", "category": "ощущения", "who": "один", "survey_tag": "ощущения", "text_ru": "Тихо подуй партнёру на кожу — на шею, за ухом, вдоль спины. Затем коснись тех же мест пальцами.", "text_en": "Breathe softly on your partner's skin — neck, behind the ear, down the spine. Then touch the same places with your fingers.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-011", "category": "ощущения", "who": "один", "survey_tag": "ощущения", "text_ru": "Проведи шёлком по плечам партнёра, потом медленно потяни его на себя — пусть следует за тканью.", "text_en": "Draw a piece of silk across your partner's shoulders, then slowly pull it so they follow the fabric toward you.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-012", "category": "массаж", "who": "один", "survey_tag": "масляный массаж", "text_ru": "Согрей масло в ладонях и сделай партнёру длинный массаж спины. Двигайся медленно и спрашивай, что приятнее.", "text_en": "Warm some massage oil in your hands and give your partner a long back massage. Go slowly and ask what feels better.", "seo_ok": false, "timer_sec": 600, "level": "goryacho"}, {"id": "g-013", "category": "массаж", "who": "один", "survey_tag": "масляный массаж", "text_ru": "Сделай массаж ног и бёдер с тёплым маслом — от стоп к коленям. Дальше только по желанию партнёра.", "text_en": "Give a leg massage with warm oil — from feet up to the knees. Go further only if your partner wants to.", "seo_ok": false, "timer_sec": 300, "level": "goryacho"}, {"id": "g-014", "category": "массаж", "who": "оба", "survey_tag": "масляный массаж", "text_ru": "Сделайте друг другу массаж по очереди: по десять минут, без разговоров. В конце просто полежите рядом.", "text_en": "Take turns giving each other a massage, ten minutes each, no talking. At the end, just lie side by side.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-015", "category": "массаж", "who": "один", "survey_tag": "масляный массаж", "text_ru": "Нарисуй маслом на спине партнёра сердце или своё имя. Потом медленно сотри его поцелуями.", "text_en": "Draw a heart or your name on your partner's back with a bit of oil. Then slowly kiss it away.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-016", "category": "ролевая", "who": "оба", "survey_tag": "ролевые сценки", "text_ru": "Вы незнакомцы в баре. Один подходит к другому с лучшей фразой для знакомства. Играйте до тех пор, пока не захочется уйти вдвоём.", "text_en": "You're strangers at a bar. One approaches the other with their best opening line. Play until you both want to leave together.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-017", "category": "ролевая", "who": "оба", "survey_tag": "ролевые сценки", "text_ru": "Сыграйте свидание вслепую: вы видите друг друга впервые и знакомитесь за ужином. Выберите вымышленные имена.", "text_en": "Act out a blind date: you're meeting for the first time over dinner. Pick made-up names.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-018", "category": "ролевая", "who": "оба", "survey_tag": "ролевые сценки", "text_ru": "Вы попутчики в ночном поезде. Разговор начинается невинно, а потом становится всё откровеннее. Остановитесь, когда захотите.", "text_en": "You're fellow travellers on a night train. The chat starts innocently and gets bolder. Stop whenever you like.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-019", "category": "ролевая", "who": "оба", "survey_tag": "ролевые сценки", "text_ru": "Сыграйте «двое, которые не должны, но не могут удержаться»: встреча на вечеринке, где вы делаете вид, что не знакомы.", "text_en": "Play \"two people who shouldn't, but can't help it\": a party where you both pretend not to know each other.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-020", "category": "ролевая", "who": "оба", "survey_tag": "ролевые сценки", "text_ru": "Один — гость отеля, второй — человек, который принёс ему ужин в номер. Придумайте, почему он задержался.", "text_en": "One of you is a hotel guest, the other brings dinner to the room. Come up with a reason why they stay a while.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-021", "category": "ролевая", "who": "оба", "survey_tag": "ролевые сценки", "text_ru": "Сыграйте встречу двух бывших, которые случайно столкнулись спустя годы. Что будет дальше — решаете вы.", "text_en": "Act out two exes who run into each other after years. What happens next is up to you.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-022", "category": "игра", "who": "один", "survey_tag": "раздеваем друг друга", "text_ru": "Медленно расстегни рубашку или молнию партнёра. После каждой пуговицы — короткий поцелуй. Остановись там, где решите.", "text_en": "Slowly undo your partner's shirt or zipper. A short kiss after every button. Stop wherever you both decide.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-023", "category": "игра", "who": "оба", "survey_tag": "раздеваем друг друга", "text_ru": "Раздевайте друг друга по очереди, по одной вещи, глядя в глаза. Каждый может сказать «хватит».", "text_en": "Undress each other in turns, one item at a time, eyes locked. Either of you can say \"enough\".", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-024", "category": "игра", "who": "один", "survey_tag": "раздеваем друг друга", "text_ru": "Партнёр стоит неподвижно. Ты помогаешь ему снять одну вещь, не торопясь, и описываешь вслух, что тебе в нём нравится.", "text_en": "Your partner stands still. You help them take off one item, unhurried, and say out loud what you like about them.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-025", "category": "игра", "who": "оба", "survey_tag": "раздеваем друг друга", "text_ru": "Сыграйте «кто быстрее разденет другого»: победителю достаётся массаж от проигравшего. Договоритесь о границах заранее.", "text_en": "Race to undress each other: the winner gets a massage from the loser. Agree on boundaries beforehand.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-026", "category": "игра", "who": "один", "survey_tag": "раздеваем друг друга", "text_ru": "Сними с партнёра одну вещь и три минуты просто смотри и говори комплименты. Без прикосновений.", "text_en": "Take off one item of your partner's clothing and just look and compliment for two minutes. No touching.", "seo_ok": false, "timer_sec": 120, "level": "goryacho"}, {"id": "g-027", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи по телу", "text_ru": "Целуй партнёра по линии от шеи к плечу и вниз по руке. Не спеши, внимательно следи за тем, как он дышит.", "text_en": "Kiss your partner along the line from neck to shoulder and down the arm. Take it slow and notice how they breathe.", "seo_ok": false, "timer_sec": 300, "level": "goryacho"}, {"id": "g-028", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи по телу", "text_ru": "Партнёр лежит на животе. Ты медленно целуешь его спину от поясницы до шеи и обратно.", "text_en": "Your partner lies on their stomach. Slowly kiss their back from waist to neck and back again.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-029", "category": "поцелуи", "who": "оба", "survey_tag": "поцелуи по телу", "text_ru": "По очереди выбирайте, куда вас поцелуют: «шея», «живот», «колено». Каждый заказывает три поцелуя.", "text_en": "Take turns choosing where you'll be kissed: \"neck\", \"stomach\", \"knee\". Each of you orders three kisses.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-030", "category": "поцелуи", "who": "один", "survey_tag": "поцелуи по телу", "text_ru": "Целуй партнёра везде, где он разрешит: пусть показывает пальцем. Если он молчит — не двигайся дальше.", "text_en": "Kiss your partner anywhere they allow: let them point. If they stay silent, don't go further.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-031", "category": "приказы", "who": "один", "survey_tag": "ведёт один", "text_ru": "Пять минут ведёшь ты: партнёр делает только то, что ты тихо скажешь. Любая просьба может быть отклонена словом «стоп».", "text_en": "You lead for five minutes: your partner does only what you quietly say. Any request can be declined with \"stop\".", "seo_ok": false, "timer_sec": 300, "level": "goryacho"}, {"id": "g-032", "category": "приказы", "who": "один", "survey_tag": "ведёт один", "text_ru": "Пять минут партнёр ведёт тебя: ты только отвечаешь. Скажи «стоп», если что-то не по душе.", "text_en": "For five minutes, your partner leads and you just respond. Say \"stop\" if anything isn't right.", "seo_ok": false, "timer_sec": 300, "level": "goryacho"}, {"id": "g-033", "category": "приказы", "who": "один", "survey_tag": "ведёт один", "text_ru": "Выбери песню и поставь её. Пока она играет, ты решаешь, где и как вы будете касаться друг друга.", "text_en": "Choose a song and play it. While it plays, you decide where and how the two of you will touch.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-034", "category": "приказы", "who": "оба", "survey_tag": "ведёт один", "text_ru": "Договоритесь о стоп-слове и сыграйте «пять минут я, пять минут ты». Потом обсудите, что вам понравилось больше всего.", "text_en": "Agree on a stop word and play \"five minutes me, five minutes you\". Afterwards, talk about what you liked best.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-035", "category": "разговор", "who": "один", "survey_tag": "откровенные слова", "text_ru": "Шёпотом расскажи партнёру о том моменте, когда он тебя особенно волновал. Без грубостей, но с чувством.", "text_en": "Whisper to your partner about a moment when they really got to you. No crudeness, but with feeling.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-036", "category": "разговор", "who": "оба", "survey_tag": "откровенные слова", "text_ru": "По очереди продолжайте фразу: «Сегодня ночью я хочу…». Никаких подробностей, только намёки.", "text_en": "Take turns finishing the sentence: \"Tonight I want…\". No details, only hints.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-037", "category": "разговор", "who": "один", "survey_tag": "откровенные слова", "text_ru": "Напиши на листке или в заметке одно смелое желание на сегодня. Партнёр читает и решает: «да», «может» или «не сегодня».", "text_en": "Write one bold wish for tonight on a note. Your partner reads it and replies: \"yes\", \"maybe\" or \"not tonight\".", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-038", "category": "разговор", "who": "оба", "survey_tag": "откровенные слова", "text_ru": "Проведите минуту, глядя друг другу в глаза и мысленно «говоря» самые смелые слова. Потом по очереди озвучьте одно.", "text_en": "Spend one minute looking into each other's eyes, silently saying your boldest words. Then take turns saying one out loud.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-039", "category": "ощущения", "who": "один", "survey_tag": "ощущения", "text_ru": "Партнёр сидит или лежит, а ты кончиками пальцев и губ чертишь на его теле дорожку от шеи до пояса — и останавливаешься.", "text_en": "Your partner sits or lies back while you trace a path with fingertips and lips from neck to waist — and then stop.", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "g-040", "category": "ощущения", "who": "оба", "survey_tag": "ощущения", "text_ru": "Приглушите свет, включите музыку и в темноте исследуйте друг друга только прикосновениями. Любой может сказать «довольно».", "text_en": "Dim the lights, put on music and explore each other in the dark by touch alone. Either of you can say \"enough\".", "seo_ok": false, "timer_sec": null, "level": "goryacho"}, {"id": "s-001", "category": "фантазия", "who": "один", "survey_tag": "тайное желание", "text_ru": "Расскажи партнёру одну свою фантазию — той степени откровенности, которую готов озвучить. Партнёр отвечает: «да», «может» или «пока нет».", "text_en": "Share one of your fantasies with your partner — at whatever level of detail you're comfortable with. They answer \"yes\", \"maybe\" or \"not yet\".", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-002", "category": "фантазия", "who": "оба", "survey_tag": "фантазии", "text_ru": "Каждый пишет на бумажке одну фантазию. Бросьте листки в шапку и вытяните один. Решите вместе: пробуем, переносим или оставляем мечтой.", "text_en": "Each of you writes one fantasy on a slip of paper. Drop them into a hat and draw one. Decide together: try it, postpone it, or keep it a dream.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-003", "category": "фантазия", "who": "один", "survey_tag": "фантазии", "text_ru": "Опиши партнёру сцену, которую ты представлял с ним. Рассказывай тихо и медленно, как будто читаешь вслух историю.", "text_en": "Describe to your partner a scene you've imagined with them. Tell it softly and slowly, as if reading a story aloud.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-004", "category": "фантазия", "who": "оба", "survey_tag": "тайное желание", "text_ru": "По очереди заканчивайте фразу: «Я давно хотел тебе сказать, что мне бы хотелось…». Слушайте без комментариев, потом поблагодарите друг друга.", "text_en": "Take turns finishing: \"I've wanted to tell you that I'd love to…\". Listen without commenting, then thank each other.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-005", "category": "фантазия", "who": "один", "survey_tag": "фантазии", "text_ru": "Расскажи, где бы вы оказались вдвоём, если бы можно было выбрать любое место на свете и целую ночь без дел.", "text_en": "Tell your partner where you'd be together if you could choose any place on earth and have a whole night free.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-006", "category": "фантазия", "who": "оба", "survey_tag": "тайное желание", "text_ru": "Договоритесь о «да–может–нет» по трём идеям: каждый называет по одной смелой. Выберите ту, где обоим «да».", "text_en": "Agree on \"yes–maybe–no\" for three ideas: each names one bold thing. Pick the one where you both say yes.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-007", "category": "фантазия", "who": "один", "survey_tag": "фантазии", "text_ru": "Напиши партнёру короткое «письмо на сегодняшнюю ночь» с намёками на то, чего ты ждёшь. Он прочитает вслух.", "text_en": "Write your partner a short \"letter for tonight\" hinting at what you're hoping for. They read it out loud.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-008", "category": "фантазия", "who": "оба", "survey_tag": "тайное желание", "text_ru": "Расскажите друг другу, что вас по-настоящему заводило вначале отношений и что, возможно, вы забыли делать.", "text_en": "Tell each other what truly thrilled you early on, and what you may have stopped doing.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-009", "category": "ролевая", "who": "оба", "survey_tag": "долгая ролевая", "text_ru": "Выберите сценарий на вечер: «секретная встреча», «актёр и поклонница», «хозяин поместья и новая гостья». Играйте минимум 30 минут. Стоп-слово обязательно.", "text_en": "Pick a scenario for the evening: \"secret rendezvous\", \"actor and admirer\", \"lord of the manor and a new guest\". Play for at least 30 minutes. A stop word is a must.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-010", "category": "ролевая", "who": "оба", "survey_tag": "долгая ролевая", "text_ru": "Сыграйте «двое после долгой разлуки»: вы не виделись год. Начните встречу на пороге и растяните её на весь вечер.", "text_en": "Play \"two people after a long separation\": you haven't seen each other in a year. Start at the door and stretch it into a whole evening.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-011", "category": "ролевая", "who": "оба", "survey_tag": "долгая ролевая", "text_ru": "Придумайте вымышленные имена и биографии. Встретьтесь «в первый раз» как два незнакомца и проведите вместе вечер по сценарию.", "text_en": "Make up names and backstories. Meet \"for the first time\" as two strangers and spend the evening following your script.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-012", "category": "ролевая", "who": "оба", "survey_tag": "долгая ролевая", "text_ru": "Сыграйте «детектив и подозреваемый»: допрос, намёки, напряжение. Ничего опасного — только игра взглядов и слов.", "text_en": "Play \"detective and suspect\": interrogation, hints, tension. Nothing dangerous — just a game of looks and words.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-013", "category": "ролевая", "who": "оба", "survey_tag": "долгая ролевая", "text_ru": "Устройте «ночь в отеле»: вы приехали в незнакомый город и поселились в одном номере. Придумайте, кто вы друг другу.", "text_en": "Stage a \"night at a hotel\": you've both arrived in a strange city and share a room. Decide who you are to each other.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-014", "category": "ролевая", "who": "оба", "survey_tag": "сюрприз", "text_ru": "Один из вас заранее готовит сценарий и не рассказывает его. Второй просто входит в комнату и играет по ходу событий.", "text_en": "One of you prepares a scenario in secret. The other simply walks in and plays along.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-015", "category": "приказы", "who": "один", "survey_tag": "приказы", "text_ru": "Десять минут ты даёшь партнёру приказы. Он выполняет всё, что можно без «стоп». Вы оба помните стоп-слово и можете использовать его в любой момент.", "text_en": "For ten minutes you give your partner orders. They follow whatever feels fine, and \"stop\" ends it. You both know the safe word and can use it any time.", "seo_ok": false, "timer_sec": 600, "level": "smelo"}, {"id": "s-016", "category": "приказы", "who": "один", "survey_tag": "приказы", "text_ru": "Теперь командует другой: десять минут приказов. Не забудьте стоп-слово и проверку: «всё хорошо?» каждые несколько минут.", "text_en": "Now the other person gives the orders: ten minutes. Remember the stop word and check in: \"all good?\" every few minutes.", "seo_ok": false, "timer_sec": 600, "level": "smelo"}, {"id": "s-017", "category": "приказы", "who": "один", "survey_tag": "приказы", "text_ru": "Партнёр выбирает пять приказов для тебя из списка, который вы составили заранее. Ты выполняешь их по порядку, не торопясь.", "text_en": "Your partner picks five orders for you from a list you wrote together beforehand. You carry them out in order, unhurried.", "seo_ok": false, "timer_sec": 300, "level": "smelo"}, {"id": "s-018", "category": "приказы", "who": "один", "survey_tag": "приказы", "text_ru": "Скажи партнёру: «Закрой глаза и жди». Подумай, что произойдёт дальше, и сделай это медленно — с проверкой, всё ли в порядке.", "text_en": "Tell your partner: \"Close your eyes and wait.\" Decide what happens next and do it slowly, checking in that everything feels right.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-019", "category": "приказы", "who": "оба", "survey_tag": "приказы", "text_ru": "Сыграйте «слуга на вечер»: один выполняет желания другого в рамках заранее оговорённого списка. Через полчаса поменяйтесь ролями.", "text_en": "Play \"servant for the evening\": one fulfils the other's wishes from a pre-agreed list. After half an hour, swap roles.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-020", "category": "приказы", "who": "один", "survey_tag": "приказы", "text_ru": "Партнёр вручает тебе три «карты желаний». Используй их, когда захочешь, а он обязан выполнить — если это в рамках стоп-слова.", "text_en": "Your partner hands you three \"wish cards\". Use them whenever you like; they must grant them — as long as the stop word isn't used.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-021", "category": "места", "who": "оба", "survey_tag": "смелые места дома", "text_ru": "Выберите в доме необычное место — кухню, подоконник, диван в гостиной. Проведите там десять минут, как будто это новая территория.", "text_en": "Pick an unusual spot at home — the kitchen, a windowsill, the living-room sofa. Spend ten minutes there as if it were new territory.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-022", "category": "места", "who": "оба", "survey_tag": "смелые места дома", "text_ru": "Примите вместе душ или ванну при свечах. Помойте друг другу спину и волосы и просто побудьте близко.", "text_en": "Share a shower or a candlelit bath. Wash each other's backs and hair and simply stay close.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-023", "category": "места", "who": "оба", "survey_tag": "смелые места дома", "text_ru": "Выключите свет везде, кроме одной лампы или свечи. Двигайтесь по дому, останавливаясь для поцелуев в каждом новом углу.", "text_en": "Turn off every light except one lamp or candle. Move through the home, pausing for a kiss in every new corner.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-024", "category": "места", "who": "оба", "survey_tag": "смелые места дома", "text_ru": "Устройте «ночь на полу»: постелите одеяла и подушки в гостиной, включите музыку и проведите вечер как в палатке.", "text_en": "Make a \"floor night\": lay out blankets and pillows in the living room, put on music and spend the evening as if in a tent.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-025", "category": "места", "who": "оба", "survey_tag": "смелые места дома", "text_ru": "Выберите комнату, где вы обычно не бываете вечером, и превратите её в свидание: свечи, музыка, никакой посторонней техники.", "text_en": "Choose a room you rarely use in the evening and turn it into a date: candles, music, no screens.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-026", "category": "места", "who": "оба", "survey_tag": "смелые места дома", "text_ru": "Если есть закрытый балкон или терраса, посидите там под одним пледом и целуйтесь, пока не замёрзнете или не захочется внутрь.", "text_en": "If you have a private balcony or terrace, sit under one blanket and kiss until you're cold or want to go back in.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-027", "category": "фото", "who": "оба", "survey_tag": "фотосессия для двоих", "text_ru": "Устройте приватную фотосессию: свет лампы, красивый ракурс, тот образ, в котором вы себя любите. Фото остаются только у вас и не уходят в сеть.", "text_en": "Do a private photo shoot: lamp light, a flattering angle, the look you love yourselves in. The photos stay with you and never go online.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-028", "category": "фото", "who": "один", "survey_tag": "фотосессия для двоих", "text_ru": "Сфотографируй партнёра так, как видишь его в самые красивые моменты. Покажи снимки — и вместе решите, что оставить, а что удалить.", "text_en": "Photograph your partner the way you see them at their most beautiful. Show them the shots, and decide together what to keep and what to delete.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-029", "category": "фото", "who": "оба", "survey_tag": "фотосессия для двоих", "text_ru": "Сделайте силуэтную съёмку: свет сзади, тени на стене. Ничего лишнего видно не будет, только форма и настроение.", "text_en": "Take silhouette shots: light from behind, shadows on the wall. Nothing explicit shows — just shape and mood.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-030", "category": "фото", "who": "оба", "survey_tag": "фотосессия для двоих", "text_ru": "Снимите друг друга на плёнку или в режиме «исчезающих» снимков. Что не понравится — удалите на месте вместе.", "text_en": "Shoot each other with a film camera or in a mode where pictures vanish. Delete anything you dislike right then, together.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-031", "category": "опыт", "who": "оба", "survey_tag": "новый опыт", "text_ru": "Каждый называет одну новую вещь, которую хотел бы попробовать вместе. Выберите ту, где обоим «хочу», и запланируйте её на ближайшие дни.", "text_en": "Each of you names one new thing you'd like to try together. Choose the one where you both say \"want\" and plan it for the next few days.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-032", "category": "опыт", "who": "оба", "survey_tag": "новый опыт", "text_ru": "Составьте «список желаний на год»: по пять идей от каждого, только мягкие и безопасные. Отметьте то, что хотите попробовать первым.", "text_en": "Make a \"wish list for the year\": five ideas from each, gentle and safe ones only. Mark the one you'd like to try first.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-033", "category": "опыт", "who": "оба", "survey_tag": "новый опыт", "text_ru": "Купите или выберите вместе что-то для игр (ткань, свечи, масло). Решите, как использовать, и обсудите, что приятнее.", "text_en": "Pick out something together for play (fabric, candles, oil). Decide how to use it and talk about what feels better.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-034", "category": "опыт", "who": "оба", "survey_tag": "сюрприз", "text_ru": "Один планирует для другого вечер-сюрприз на ближайшую неделю. Другой ничего не знает, кроме одного слова-подсказки.", "text_en": "One of you plans a surprise evening for the other within the coming week. The other knows nothing except one hint word.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-035", "category": "опыт", "who": "оба", "survey_tag": "новый опыт", "text_ru": "Договоритесь о «зелёном, жёлтом и красном свете»: слова для «ещё», «потише» и «стоп». Потом в течение вечера пользуйтесь ими.", "text_en": "Agree on \"green, yellow and red lights\": words for \"more\", \"slower\" and \"stop\". Then use them throughout the evening.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-036", "category": "опыт", "who": "оба", "survey_tag": "сюрприз", "text_ru": "Составьте друг другу «сюрприз-конверт»: идея на бумажке для сегодняшнего вечера. Откройте их одновременно и выполните то, что совпадёт.", "text_en": "Prepare each other a \"surprise envelope\": an idea on paper for tonight. Open them at the same time and do whatever overlaps.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-037", "category": "разговор", "who": "оба", "survey_tag": "тайное желание", "text_ru": "Закончите вечер откровенным разговором: что понравилось, что было неловко, что хотите повторить. Без оценок — только «спасибо».", "text_en": "End the evening with an honest talk: what you liked, what felt awkward, what to repeat. No scoring — only \"thank you\".", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-038", "category": "фантазия", "who": "оба", "survey_tag": "фантазии", "text_ru": "Нарисуйте или напишите вдвоём «сценарий идеальной ночи». Каждый добавляет по одной строчке по очереди, пока история не закончится.", "text_en": "Co-write or draw a \"script for the perfect night\". Take turns adding one line each until the story ends.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-039", "category": "фантазия", "who": "оба", "survey_tag": "фантазии", "text_ru": "Включите музыку и по очереди «закажите» друг другу настроение вечера одним словом: «нежно», «дерзко», «лениво». Следуйте заказу весь вечер.", "text_en": "Put on music and take turns \"ordering\" the mood of the evening in a single word: \"tender\", \"daring\", \"lazy\". Follow the order all night.", "seo_ok": false, "timer_sec": null, "level": "smelo"}, {"id": "s-040", "category": "приказы", "who": "один", "survey_tag": "приказы", "text_ru": "Партнёр отдаёт тебе одну короткую команду шёпотом, а ты выполняешь её максимально медленно. Потом меняетесь. Стоп-слово всегда рядом.", "text_en": "Your partner whispers one short command and you carry it out as slowly as you can. Then swap. The stop word is always close.", "seo_ok": false, "timer_sec": null, "level": "smelo"}], "survey_tags": [{"tag": "комплименты", "tag_en": "compliments", "question_ru": "Хотите обмениваться комплиментами — вслух, без спешки и без шуток в сторону?", "question_en": "Want to trade compliments out loud — unhurried, and without turning them into jokes?", "level": "nezhno"}, {"tag": "объятия", "tag_en": "hugs", "question_ru": "Хотите просто обниматься: долго, тихо, без продолжения?", "question_en": "Want to just hold each other — for a while, quietly, with nothing else expected?", "level": "nezhno"}, {"tag": "массаж рук", "tag_en": "hand massage", "question_ru": "Хотите делать друг другу массаж рук?", "question_en": "Want to give each other a hand massage?", "level": "nezhno"}, {"tag": "массаж плеч и спины", "tag_en": "shoulder and back massage", "question_ru": "Хотите делать лёгкий массаж плеч или спины через одежду?", "question_en": "Want to give a light shoulder or back massage, over clothes?", "level": "nezhno"}, {"tag": "прикосновения", "tag_en": "light touches", "question_ru": "Хотите мягкие прикосновения: ладони, волосы, спина, без перехода дальше?", "question_en": "Want gentle touching — hands, hair, back — with no expectation it goes further?", "level": "nezhno"}, {"tag": "разговоры о нас", "tag_en": "talking about us", "question_ru": "Хотите спокойно поговорить о ваших отношениях: что цените, что замечаете, чего ждёте?", "question_en": "Want to talk quietly about your relationship — what you value, notice, and hope for?", "level": "nezhno"}, {"tag": "воспоминания", "tag_en": "memories", "question_ru": "Хотите вспоминать ваши общие моменты: первую встречу, смешные случаи, важные дни?", "question_en": "Want to go back through your shared memories — the first meeting, funny moments, days that mattered?", "level": "nezhno"}, {"tag": "планы на двоих", "tag_en": "plans for two", "question_ru": "Хотите вместе придумывать маленькие планы: куда сходить, что приготовить, о чём мечтаете?", "question_en": "Want to invent small plans together — a place to go, something to cook, something you both dream about?", "level": "nezhno"}, {"tag": "игры взглядами", "tag_en": "eye contact games", "question_ru": "Хотите игры с взглядом: смотреть друг на друга, не отводя глаз, и угадывать настроение?", "question_en": "Want eye-contact games — holding a gaze and guessing each other's mood?", "level": "nezhno"}, {"tag": "медленный танец", "tag_en": "slow dancing", "question_ru": "Хотите медленно потанцевать дома, даже если музыки почти нет?", "question_en": "Want to slow-dance at home, even if the music is just whatever is on?", "level": "nezhno"}, {"tag": "записки и послания", "tag_en": "notes and messages", "question_ru": "Хотите оставлять друг другу короткие записки или послания на вечер?", "question_en": "Want to leave each other short notes or little messages tonight?", "level": "nezhno"}, {"tag": "забота", "tag_en": "care", "question_ru": "Хотите простые жесты заботы: чай, плед, удобное место, внимание к мелочам?", "question_en": "Want simple caretaking — tea, a blanket, a comfortable spot, attention to small things?", "level": "nezhno"}, {"tag": "держать за руки", "tag_en": "holding hands", "question_ru": "Хотите просто держать друг друга за руки и быть рядом, даже почти не разговаривая?", "question_en": "Want to just hold hands and sit close, even without talking much?", "level": "nezhno"}, {"tag": "шёпот", "tag_en": "whispering", "question_ru": "Хотите говорить друг другу тёплые вещи шёпотом, близко?", "question_en": "Want to say warm things to each other in a close whisper?", "level": "nezhno"}, {"tag": "весёлые задания", "tag_en": "playful dares", "question_ru": "Хотите лёгкие смешные задания и маленькие вызовы без смущения?", "question_en": "Want light, funny little dares and challenges — nothing embarrassing?", "level": "nezhno"}, {"tag": "флирт без продолжения", "tag_en": "flirting with no follow-through", "question_ru": "Хотите лёгкий флирт: взгляды, улыбки, поддразнивания, без перехода к сексу?", "question_en": "Want light flirting — looks, smiles, teasing — with no pressure to take it further?", "level": "nezhno"}, {"tag": "благодарности", "tag_en": "gratitude", "question_ru": "Хотите вслух говорить, за что вы благодарны друг другу в обычной жизни?", "question_en": "Want to say out loud what you are grateful for in each other, in ordinary life?", "level": "nezhno"}, {"tag": "угадайки о нас", "tag_en": "how well we know each other", "question_ru": "Хотите игры на знание друг друга: угадывать ответы, привычки, любимые мелочи?", "question_en": "Want games about how well you know each other — guesses about habits, favourites, little details?", "level": "nezhno"}, {"tag": "фото вместе", "tag_en": "photos together", "question_ru": "Хотите сделать одно тёплое совместное фото — для себя, не для ленты?", "question_en": "Want to take one warm photo together — for the two of you, not for a feed?", "level": "nezhno"}, {"tag": "тишина рядом", "tag_en": "quiet closeness", "question_ru": "Хотите просто побыть рядом в тишине: сидеть, лежать, слушать дыхание?", "question_en": "Want to just be close in silence — sit or lie together and listen to each other breathe?", "level": "nezhno"}, {"tag": "поцелуи", "tag_en": "kisses", "question_ru": "Хотите больше поцелуев — долгих, медленных, в разных местах?", "question_en": "Want more kisses — long, slow, and in unexpected places?", "level": "teplo"}, {"tag": "шёпот", "tag_en": "whispering", "question_ru": "Хотите шептать друг другу на ухо — признания, дразнилки, комплименты?", "question_en": "Want to whisper in each other's ear — confessions, teasing, compliments?", "level": "teplo"}, {"tag": "массаж плеч и спины", "tag_en": "shoulder and back massage", "question_ru": "Хотите массаж плеч и спины — друг другу, не торопясь?", "question_en": "Want a shoulder and back massage — for each other, unhurried?", "level": "teplo"}, {"tag": "массаж ног", "tag_en": "foot massage", "question_ru": "Хотите массаж стоп и ног?", "question_en": "Want a foot and leg massage?", "level": "teplo"}, {"tag": "флирт", "tag_en": "flirting", "question_ru": "Хотите флиртовать друг с другом, как в начале?", "question_en": "Want to flirt with each other like at the very beginning?", "level": "teplo"}, {"tag": "лёгкое раздевание", "tag_en": "light undressing", "question_ru": "Хотите задания, где снимается одна вещь одежды — по желанию и не больше?", "question_en": "Want tasks where one item of clothing comes off — only if you like, and no more?", "level": "teplo"}, {"tag": "танец", "tag_en": "slow dance", "question_ru": "Хотите медленный танец вдвоём, вплотную?", "question_en": "Want a slow dance together, close?", "level": "teplo"}, {"tag": "дразнилки", "tag_en": "teasing", "question_ru": "Хотите игры с лёгким поддразниванием и ожиданием?", "question_en": "Want games of light teasing and anticipation?", "level": "teplo"}, {"tag": "повязка на глаза", "tag_en": "blindfold", "question_ru": "Хотите игры с завязанными глазами?", "question_en": "Want games with a blindfold?", "level": "goryacho"}, {"tag": "ощущения", "tag_en": "sensations", "question_ru": "Хотите играть с ощущениями: лёд, перо, шёлк, тёплое масло?", "question_en": "Want to play with sensations: ice, feather, silk, warm massage oil?", "level": "goryacho"}, {"tag": "масляный массаж", "tag_en": "oil massage", "question_ru": "Хотите чувственный массаж с тёплым маслом?", "question_en": "Want a sensual massage with warm oil?", "level": "goryacho"}, {"tag": "ролевые сценки", "tag_en": "role scenes", "question_ru": "Хотите короткие ролевые сценки — «незнакомцы», «свидание вслепую» и так далее?", "question_en": "Want short role-play scenes — \"strangers\", \"blind date\" and so on?", "level": "goryacho"}, {"tag": "раздеваем друг друга", "tag_en": "undressing each other", "question_ru": "Хотите раздевать друг друга — медленно, по очереди?", "question_en": "Want to undress each other — slowly, in turns?", "level": "goryacho"}, {"tag": "поцелуи по телу", "tag_en": "body kisses", "question_ru": "Хотите поцелуи не только в губы, но и по всему телу?", "question_en": "Want kisses beyond the lips — all over?", "level": "goryacho"}, {"tag": "ведёт один", "tag_en": "one leads", "question_ru": "Хотите, чтобы один партнёр вёл вечер несколько минут, а другой доверялся?", "question_en": "Want one partner to lead for a few minutes while the other simply goes along?", "level": "goryacho"}, {"tag": "откровенные слова", "tag_en": "spicy talk", "question_ru": "Хотите говорить друг другу смелые слова — намёками, без грубости?", "question_en": "Want to say bold things to each other — hinted, never crude?", "level": "goryacho"}, {"tag": "фантазии", "tag_en": "fantasies", "question_ru": "Хотите делиться фантазиями — вслух и без осуждения?", "question_en": "Want to share fantasies — out loud and without judgement?", "level": "smelo"}, {"tag": "тайное желание", "tag_en": "secret desire", "question_ru": "Готовы рассказать партнёру одно тайное желание — а он ответит «да», «может» или «пока нет»?", "question_en": "Ready to tell your partner one secret desire — and let them answer \"yes\", \"maybe\" or \"not yet\"?", "level": "smelo"}, {"tag": "долгая ролевая", "tag_en": "long role play", "question_ru": "Хотите долгую ролевую игру с продуманным сценарием?", "question_en": "Want a longer role play with a proper storyline?", "level": "smelo"}, {"tag": "приказы", "tag_en": "orders", "question_ru": "Хотите игру «партнёр командует десять минут» со стоп-словом?", "question_en": "Want the \"partner gives the orders for ten minutes\" game, with a stop word?", "level": "smelo"}, {"tag": "смелые места дома", "tag_en": "bold places at home", "question_ru": "Хотите менять обстановку: кухня, душ, балкон — осторожно и без риска, что увидят?", "question_en": "Want to change the setting: kitchen, shower, balcony — safely, with no risk of being seen?", "level": "smelo"}, {"tag": "фотосессия для двоих", "tag_en": "photo shoot for two", "question_ru": "Хотите приватную фотосессию — только для вас двоих и без публикации?", "question_en": "Want a private photo shoot — just for the two of you, never shared?", "level": "smelo"}, {"tag": "новый опыт", "tag_en": "new experiences", "question_ru": "Хотите вместе попробовать что-то новое — по согласованному списку?", "question_en": "Want to try something new together — from a list you both agreed on?", "level": "smelo"}, {"tag": "сюрприз", "tag_en": "surprise", "question_ru": "Хотите сюрпризы: сценарий, который готовит один, а второй не знает деталей?", "question_en": "Want surprises: a scenario prepared by one, with the details hidden from the other?", "level": "smelo"}]};